WITH with_windows AS (SELECT *, LAG(monthly_fee, 1) OVER (PARTITION BY plan ORDER BY monthly_fee ASC, id ASC) AS prev_monthly_fee, SUM(monthly_fee) OVER (PARTITION BY plan, status ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, FIRST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY plan ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee, LAG(monthly_fee, 1) OVER (PARTITION BY customer_id ORDER BY monthly_fee ASC, id ASC) AS prev_monthly_fee_2 FROM subscriptions WHERE monthly_fee < 80) SELECT status, customer_id, CASE WHEN prev_monthly_fee >= 213 THEN 'LARGE' ELSE 'SMALL' END AS prev_monthly_fee_tier, APPROX_PERCENTILE(cumulative_monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS cumulative_monthly_fee_quartiles, APPROX_PERCENTILE(monthly_fee, 0.9) AS monthly_fee_p90, SIZE(COLLECT_SET(plan)) AS num_plans FROM with_windows GROUP BY GROUPING SETS ((status, customer_id, CASE WHEN prev_monthly_fee >= 213 THEN 'LARGE' ELSE 'SMALL' END), (status, customer_id)) ORDER BY num_plans DESC NULLS LAST
